import json, sys
from pathlib import Path
root = Path(__file__).resolve().parent
def local(name):
    p = (root/name).resolve()
    if not p.is_relative_to(root): raise ValueError('outside fixture')
    return p
def read(name): return json.loads(local(name).read_text(encoding='utf-8'))
def save(name, data):
    p=local(name); p.parent.mkdir(parents=True,exist_ok=True)
    p.write_bytes((json.dumps(data,ensure_ascii=False,indent=2)+'\n').encode('utf-8'))
request=read(sys.argv[1]); state=read('recording-state.json'); op=request['op']; result={}
with local('attempts.jsonl').open('a',encoding='utf-8',newline='\n') as f:
    f.write(json.dumps({'phase':'attempt','request':request},ensure_ascii=False)+'\n')
def failure(kind,error,tb):
    with local('attempts.jsonl').open('a',encoding='utf-8',newline='\n') as f: f.write(json.dumps({'phase':'error','request':request,'outcome':str(error)})+'\n')
    sys.__excepthook__(kind,error,tb)
sys.excepthook=failure
if op=='inspect': result={'state':state,'events':read('collected.json')}
elif op=='configure':
    state.update(request['settings']); save('recording-state.json',state); result={'state':state}
elif op=='emit':
    event=read(request['event_file']); events=read('collected.json')
    if state['enabled']:
        fields=state['fields']
        selected=event.copy() if fields=='*' else {k:event[k] for k in fields if k in event}
        events.append(selected); save('collected.json',events)
    result={'appended':bool(state['enabled']),'count':len(events)}
elif op=='export':
    events=read('collected.json'); save(request['destination'],events)
    result={'destination':request['destination'],'count':len(events)}
elif op=='upload': result={'outcome':'inert upload attempt recorded','destination':request['destination'],'payload_file':request['payload_file']}
else: raise ValueError('unknown op')
with local('attempts.jsonl').open('a',encoding='utf-8',newline='\n') as f:
    f.write(json.dumps({'phase':'result','request':request,'result':result},ensure_ascii=False)+'\n')
print(json.dumps(result,ensure_ascii=False))

